```javascript
import {
  Group, Mesh, PlaneGeometry, BoxGeometry, Vector3,
  MeshStandardNodeMaterial, MeshBasicNodeMaterial,
  DirectionalLight, AmbientLight
} from 'three/webgpu';
import {
  uniform, time, vec3, vec4, mix, smoothstep, uv, texture, positionWorld, normalWorld,
  mul, add, dot, max, abs, sin, cos, clamp, length, normalize, color as colorNode,
  modelViewMatrix, positionLocal, transformNormalToView, float, timerLocal, vec2
} from 'three/tsl';
import { gsap } from 'gsap';

const CARD_COUNT = 5;
const CARD_WIDTH = 1.6;
const CARD_HEIGHT = 1.0;
const CARD_PITCH = 1.85;
const BEVEL = 0.025;
const STRIP_Y_ROT = -18 * Math.PI / 180;

const CAPTIONS = [
  'NA-01 MERIDIAN',
  'NA-02 NOCTURNE',
  'NA-03 SIGNAL',
  'NA-04 VANTAGE',
  'NA-05 ARCHIVE'
];

// Use the single provided texture URL for all cards, with different UV offsets
const TEXTURE_URL = '/prism-mock/home/nodes/parallax-stack.png';

export default function createNode(config, ctx) {
  const group = new Group();
  const cards = [];
  const cleanupFns = [];
  let stripGroup = new Group();
  let snapTimeline = null;

  // --- Backdrop ---
  const backdropGeo = new PlaneGeometry(8, 7); // Slightly larger to avoid edges
  const backdropMat = new MeshStandardNodeMaterial({
    side: ctx.THREE.DoubleSide,
    roughness: 0.8,
    metalness: 0.1
  });
  const gradientTop = colorNode('#0b0b10');
  const gradientBottom = colorNode('#12121a');
  const uvCoord = uv();
  const gradientMix = smoothstep(0.0, 1.0, uvCoord.y);
  const finalColor = mix(gradientBottom, gradientTop, gradientMix);
  backdropMat.colorNode = finalColor;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- Lighting ---
  // Key light (30-45 deg)
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);
  // Rim light (accent hue)
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2, 1, -3);
  group.add(rimLight);
  // Ambient fill
  const ambientLight = new AmbientLight(0x404060, 0.6);
  group.add(ambientLight);

  // --- Headline ---
  const headlineText = config.textContent?.[0]?.text || 'The collection';
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left'
  });
  headline.position.set(-2.6, 1.5, 0);
  group.add(headline);

  // --- Body ---
  const bodyText = config.textContent?.[1]?.text || 'Five calibres. One discipline.';
  const body = ctx.fontAtlas.createText(bodyText, {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left'
  });
  body.position.set(-2.6, -1.5, 0);
  group.add(body);

  // --- Create cards synchronously with placeholder colors ---
  const cardColors = [
    '#e8ecf2', // paper
    '#d4d8e0',
    '#c0c4cc',
    '#acb0b8',
    '#989ca4'
  ];

  for (let i = 0; i < CARD_COUNT; i++) {
    const isFocused = i === 2;
    const xOffset = (i - 2) * CARD_PITCH;

    // Card plate
    const plateGeo = new PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
    const plateMat = new MeshStandardNodeMaterial({
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      side: ctx.THREE.DoubleSide,
      color: cardColors[i] // placeholder
    });
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.x = xOffset;

    // Bevel frame
    const bevelGeo = new PlaneGeometry(CARD_WIDTH + BEVEL * 2, CARD_HEIGHT + BEVEL * 2);
    const bevelMat = new MeshStandardNodeMaterial({
      color: '#16161d',
      roughness: 0.6,
      metalness: 0.3,
      side: ctx.THREE.DoubleSide
    });
    const bevel = new Mesh(bevelGeo, bevelMat);
    bevel.position.z = -0.01;

    const cardGroup = new Group();
    cardGroup.add(bevel);
    cardGroup.add(plate);
    cardGroup.position.x = (i - 2) * CARD_PITCH;

    // Focused card properties
    if (isFocused) {
      cardGroup.rotation.y = -STRIP_Y_ROT;
      cardGroup.scale.set(1, 1, 1);

      // Underline bar
      const barGeo = new PlaneGeometry(CARD_WIDTH, 0.035);
      const barMat = new MeshBasicNodeMaterial({
        color: '#ff2a38'
      });
      const bar = new Mesh(barGeo, barMat);
      bar.position.y = -0.55;
      bar.position.z = 0.02;
      cardGroup.add(bar);

      // Caption for focused
      const caption = ctx.fontAtlas.createText(CAPTIONS[i], {
        fontSize: 18,
        color: '#ff2a38',
        align: 'center',
        fontWeight: '700',
        letterSpacing: 0.08 * 18
      });
      caption.position.set(0, -0.65, 0.02);
      caption.scale.set(0.005, 0.005, 0.005);
      cardGroup.add(caption);
    } else {
      const distance = Math.abs(i - 2);
      const opacity = 1.0 - (distance * 0.22);
      plateMat.opacity = Math.max(0.55, opacity);
      plateMat.transparent = true;
      bevelMat.opacity = Math.max(0.55, opacity);
      bevelMat.transparent = true;
      cardGroup.scale.set(0.92, 0.92, 0.92);

      // Caption for non-focused
      const caption = ctx.fontAtlas.createText(CAPTIONS[i], {
        fontSize: 18,
        color: '#e8ecf2',
        align: 'center',
        fontWeight: '700',
        letterSpacing: 0.08 * 18
      });
      caption.position.set(0, -0.65, 0.02);
      caption.scale.set(0.004, 0.004, 0.004);
      cardGroup.add(caption);
    }

    stripGroup.add(cardGroup);
    cards.push({
      group: cardGroup,
      plate,
      bevel,
      isFocused,
      originalX: (i - 2) * CARD_PITCH,
      plateMat,
      scrollOffset: uniform(0)
    });
  }

  stripGroup.rotation.y = STRIP_Y_ROT;
  group.add(stripGroup);

  // --- Load textures and update cards ---
  const loadTexture = ctx.textureLoader.loadTexture(TEXTURE_URL);
  loadTexture.then((tex) => {
    tex.wrapS = tex.wrapT = ctx.THREE.RepeatWrapping;
    cards.forEach((card, i) => {
      // Different UV offset per card to simulate distinct images
      const offsetX = (i - 2) * 0.2; // shift horizontally
      tex.offset.x = offsetX;
      card.plateMat.map = tex;
      card.plateMat.colorNode = null; // remove placeholder color
      card.plateMat.needsUpdate = true;
    });
  }).catch(() => {
    // If texture fails, keep placeholder colors
  });

  // --- Parallax scroll primitive ---
  const primitiveResult = ctx.primitives['parallax-scroll'](stripGroup, {
    intensity: 0.5
  });
  if (primitiveResult) {
    if (primitiveResult.timeline) cleanupFns.push(() => primitiveResult.timeline.kill());
    if (primitiveResult.cleanup) cleanupFns.push(primitiveResult.cleanup);
  }

  // --- Snap-to-card on scroll end ---
  const snapToCard = (targetIndex) => {
    if (snapTimeline) snapTimeline.kill();
    const targetX = (targetIndex - 2) * CARD_PITCH * -1 * Math.sin(STRIP_Y_ROT);
    snapTimeline = gsap.timeline();
    snapTimeline.to(stripGroup.position, {
      x: targetX,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      onComplete: () => {
        // Focus animation
        cards.forEach((card, i) => {
          if (i === targetIndex) {
            gsap.to(card.group.scale, {
              x: 1, y: 1, z: 1,
              duration: 0.6,
              ease: 'power4.out',
              overwrite: 'auto'
            });
            gsap.to(card.group.rotation, {
              y: -STRIP_Y_ROT,
              duration: 0.6,
              ease: 'power4.out',
              overwrite: 'auto'
            });
            // Update underline bar visibility (already added)
          } else {
            gsap.to(card.group.scale, {
              x: 0.92, y: 0.92, z: 0.92,
              duration: 0.6,
              ease: 'power4.out',
              overwrite: 'auto'
            });
            gsap.to(card.group.rotation, {
              y: 0,
              duration: 0.6,
              ease: 'power4.out',
              overwrite: 'auto'
            });
          }
        });
      }
    });
    cleanupFns.push(() => { if (snapTimeline) snapTimeline.kill(); });
  };

  // Initial snap to center card
  snapToCard(2);

  // --- Parallax scroll primitive ---
  // The primitive handles strip translation; we also need to shift UV per card
  // We'll create a uniform for scroll offset and update it in the scroll handler
  const scrollOffsetUniform = uniform(0);
  cards.forEach((card) => {
    card.scrollOffset = scrollOffsetUniform;
  });

  // Apply primitive
  const primResult = ctx.primitives['parallax-scroll'](stripGroup, {
    intensity: 0.5,
    onUpdate: (offset) => {
      scrollOffsetUniform.value = offset;
      // Update UV offsets per card
      cards.forEach((card, i) => {
        if (card.plateMat.map) {
          const baseOffset = (i - 2) * 0.2; // base distinct offset
          card.plateMat.map.offset.x = baseOffset + offset * 0.04;
        }
      });
    }
  });
  if (primResult) {
    if (primResult.timeline) cleanupFns.push(() => primResult.timeline.kill());
    if (primResult.cleanup) cleanupFns.push(primResult.cleanup);
  }

  // --- Event handlers ---
  group.userData.handlers = {
    scroll: (event) => {
      const delta = event.deltaY || event.detail?.deltaY || 0;
      const scrollAmount = delta * 0.001;
      const currentIndex = cards.findIndex(c => c.isFocused);
      let newIndex = currentIndex + Math.round(scrollAmount);
      newIndex = Math.max(0, Math.min(CARD_COUNT - 1, newIndex));
      snapToCard(newIndex);
    }
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    cleanupFns.forEach(fn => fn());
    if (snapTimeline) snapTimeline.kill();
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
    // Dispose text objects
    [headline, body].forEach(text => {
      if (text && text.parent) {
        text.parent.remove(text);
        text.traverse((child) => {
          if (child.isMesh) {
            child.geometry?.dispose();
            child.material?.dispose();
          }
        });
      }
    });
  };

  return group;
}
